<?php
namespace Tests\Feature;
use Tests\TestCase;use Tests\Concerns\MarketingEditingFixtures;use Illuminate\Foundation\Testing\RefreshDatabase;use App\Services\Marketing\MarketingSemanticFacts;
class MarketingSemanticFactsTest extends TestCase {
 use RefreshDatabase,MarketingEditingFixtures;
 public function test_qualification_is_never_detached_from_the_claim_even_across_paragraphs():void {[$p,$f]=$this->source();$text='仅限平整硬化场地。可以直接卸货。';$p->update(['snapshot'=>['title'=>'货柜','description'=>$text]]);$p->currentRevision->update(['context'=>array_replace($p->currentRevision->context,['snapshot'=>$p->snapshot])]);$atoms=app(MarketingSemanticFacts::class)->catalogue($f)['atoms'];$this->assertNull(collect($atoms)->firstWhere('text','可以直接卸货。'));$this->assertNotNull(collect($atoms)->firstWhere('text',$text));}
 private function source():array {[$p,$f]=$this->editingFilm();$p->update(['snapshot'=>['title'=>'货柜','description'=>'不适合冷藏。仅在确认现场条件后交付。设备、材料与一般货物。'],'brief'=>array_replace($p->brief,['source_confirmed'=>true,'facts_confirmed'=>true,'facts'=>''])]);$p->currentRevision->update(['context'=>array_replace($p->currentRevision->context,['snapshot'=>$p->snapshot,'brief'=>$p->brief])]);return [$p,$f];}
 public function test_confirmed_snapshot_is_used_when_brief_facts_empty():void {[$p,$f]=$this->source();$c=app(MarketingSemanticFacts::class)->catalogue($f);$a=collect($c['atoms'])->firstWhere('text','不适合冷藏。仅在确认现场条件后交付。设备、材料与一般货物。');$this->assertNotNull($a);$card=app(MarketingSemanticFacts::class)->card(['title_key'=>'purpose','body_fact_id'=>$a['id']],$c,2);$this->assertSame('不适合冷藏。仅在确认现场条件后交付。设备、材料与一般货物。',$card['body']);$this->assertSame('产品用途',$card['title']);$this->assertSame([$a['id']],$card['fact_ids']);}
 public function test_unconfirmed_or_changed_revision_is_rejected():void {[$p,$f]=$this->source();$service=app(MarketingSemanticFacts::class);$old=$service->catalogue($f);$p->update(['snapshot'=>['title'=>'changed']]);$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpExceptionInterface::class);$service->assertFresh($f,$old);}
 public function test_negation_conditions_and_numbers_are_not_substring_matched():void {[$p,$f]=$this->source();$s=app(MarketingSemanticFacts::class);$c=$s->catalogue($f);$negative=collect($c['atoms'])->firstWhere('text','不适合冷藏。仅在确认现场条件后交付。设备、材料与一般货物。');$this->assertSame('不适合冷藏。仅在确认现场条件后交付。设备、材料与一般货物。',$s->card(['title_key'=>'before','body_fact_id'=>$negative['id']],$c,1)['body']);$this->expectException(\Illuminate\Validation\ValidationException::class);$s->card(['title_key'=>'before','body_fact_id'=>$negative['id'],'body'=>'适合冷藏。'],$c,1);}
 public function test_unknown_fact_contact_or_overlength_copy_is_rejected():void {[$p,$f]=$this->source();$s=app(MarketingSemanticFacts::class);$c=$s->catalogue($f);$this->expectException(\Illuminate\Validation\ValidationException::class);$s->card(['title_key'=>'feature','body_fact_id'=>'invented','contact'=>'123'],$c,1);}
 public function test_unconfirmed_facts_and_overlength_atoms_are_not_eligible():void {[$p,$f]=$this->source();$p->update(['snapshot'=>['title'=>'货柜','description'=>str_repeat('长',41).'。']]);$p->currentRevision->update(['context'=>array_replace($p->currentRevision->context,['snapshot'=>$p->snapshot])]);$c=app(MarketingSemanticFacts::class)->catalogue($f);$long=collect($c['atoms'])->first(fn($a)=>mb_strlen($a['text'])>40);$this->assertFalse($long['card_eligible']);$p->update(['brief'=>array_replace($p->brief,['facts_confirmed'=>false])]);$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpExceptionInterface::class);app(MarketingSemanticFacts::class)->catalogue($f);}
}
